{
  "items": [
    {
      "title": "GENESIS-Online Database – German Federal Statistical Office (Destatis)",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/api-webservice.html",
      "justification": "Official German statistical database containing comprehensive economic data for the 2010s and 2020s. Includes GDP, economic growth, employment, wages, industrial production, government finances, investment, and business activity. Particularly useful for examining Germany's social market economy, structural economic changes, and long-term development. Data are available in CSV and XLSX formats and through an API."
    },
    {
      "title": "World Development Indicators – Germany (World Bank)",
      "url_or_doi": "https://databank.worldbank.org/reports.aspx?country=DEU&period=&series=&source=2",
      "justification": "Comprehensive dataset covering Germany's economic development during the 2010s and 2020s. Includes GDP growth, GDP per capita, inflation, unemployment, foreign direct investment, international trade, productivity-related indicators, and development measures. Particularly useful for comparing Germany's economic performance with other developed and emerging economies."
    },
    {
      "title": "AMECO – Annual Macro-Economic Database (European Commission)",
      "url_or_doi": "https://economy-finance.ec.europa.eu/economic-research-and-databases/economic-databases/ameco-database/download-annual-data-set-macro-economic-database-ameco_en",
      "justification": "European Commission database providing annual macroeconomic indicators for Germany and other European economies. Includes GDP, capital formation, employment, unemployment, wages, government expenditure, public debt, and economic productivity. Especially relevant for investigating Germany's fiscal policies, economic structure, investment patterns, and development from 2010 through the 2020s. Offers downloadable CSV and Excel datasets."
    },
    {
      "title": "Eurostat – National Accounts Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/national-accounts",
      "justification": "Official European statistical resource covering Germany's economic output, GDP composition, household consumption, investment, employment, and sectoral economic activity. Provides harmonized data suitable for examining structural transformations in Germany's economy during the 2010s and 2020s and comparing developments across EU member states."
    },
    {
      "title": "Eurostat – Regional Gross Domestic Product by NUTS 3 Region",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/view/nama_10r_3gdp?lang=en",
      "justification": "Regional GDP dataset allowing detailed analysis of economic development across German districts and urban regions. Particularly useful for studying economic disparities between eastern and western Germany, regional industrial concentration, urban economic development, and geographical differences in economic performance during the 2010s and 2020s."
    },
    {
      "title": "Eurostat – Regional Economic Accounts",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/reg_eco10_esms.htm",
      "justification": "Regional economic accounts covering GDP, gross value added, employment, and capital formation across European regions, including Germany. Data extend from 2000 into the 2020s, enabling comparisons across both decades. Useful for analyzing regional economic development, differences in productivity, industrial restructuring, and uneven economic growth."
    },
    {
      "title": "Eurostat – German Regional Economic Accounts",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/EN/reg_eco10_esms_de.htm",
      "justification": "Germany-specific documentation and statistical coverage of regional economic accounts, including GDP, gross value added by industry, employment, and investment-related indicators. Relevant for investigating structural differences between German federal states, regional economic specialization, and long-term development patterns. Particularly valuable for studies of regional convergence and persistent economic disparities."
    },
    {
      "title": "Destatis – Short-Term Economic Indicators",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/short-term-indicators.html",
      "justification": "Official German economic time-series resource providing monthly and quarterly indicators related to industrial production, employment, and other aspects of economic activity. Useful for analyzing business cycles, economic fluctuations, and Germany's economic response to major disruptions during the 2010s and 2020s. Historical data remain available, although the standalone short-term indicators service was scheduled for discontinuation in October 2026, with the underlying statistics accessible through GENESIS-Online."
    },
    {
      "title": "Eurostat – National Accounts Data and Methodology",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/national-accounts/information-data",
      "justification": "Official Eurostat resource explaining and providing access to harmonized national accounts datasets based on the European System of Accounts 2010 framework. Relevant for examining Germany's GDP, employment, investment, government activity, and sectoral development. Particularly valuable for ensuring methodological consistency when comparing German economic indicators across the 2010s and 2020s."
    },
    {
      "title": "World Bank – Germany Gross National Savings",
      "url_or_doi": "https://databank.worldbank.org/reports.aspx?country=DEU&series=NY.GNS.ICTR.CD&source=2",
      "justification": "Germany-specific World Bank time series focusing on gross national savings. Useful for studying capital accumulation, savings behavior, investment capacity, and macroeconomic development throughout the 2010s and 2020s. Can support research into Germany's export-oriented economic model, domestic investment patterns, and relationships between national savings and economic growth."
    }
  ]
}
